struct PPLLNode {
      color: u32,      // Packed RGBA8 (4 bytes)
      depth: f32,      // Fragment depth value in [0..1] (4 bytes)
      next: u32        // Index pointing to previous head node (4 bytes)
  };

// 1. Increment global atomic node counter
let nodeIdx = atomicAdd(&atomicCounter, 1u);

// 2. Ensure node pool capacity is not exceeded
if (nodeIdx < uniforms.maxNodes) {
    let pixelCoord = vec2<u32>(in.position.xy);
    let pixelIdx = pixelCoord.y * uniforms.width + pixelCoord.x;

    // 3. Atomically swap head pointer: returns previous head index
    let prevHead = atomicExchange(&headPointers[pixelIdx], nodeIdx);

    // 4. Store node data in GPU storage buffer
    nodePool[nodeIdx].color = pack4x8unorm(fragColor);
    nodePool[nodeIdx].depth = in.position.z;
    nodePool[nodeIdx].next  = prevHead;
}

var count: u32 = 0u;
   var curr: u32 = headPointers[pixelIdx];

   while (curr != 0xFFFFFFFFu && count < 16u) {
       let node = nodePool[curr];
       let d = node.depth;
       let c = unpack4x8unorm(node.color);

       // Insertion sort into local register array
       var j: u32 = count;
       while (j > 0u && sortedDepths[j - 1u] > d) {
           sortedDepths[j] = sortedDepths[j - 1u];
           sortedColors[j] = sortedColors[j - 1u];
           j = j - 1u;
       }
       sortedDepths[j] = d;
       sortedColors[j] = c;
       count = count + 1u;
       curr = node.next;
   }

